{
    int copied = 0;
    struct sk_buff *skb;
    const struct tcp_sock *tp = tcp_sk(sk);
    unsigned int seq;

    if (sk->sk_state == TCP_LISTEN)
        return -EAGAIN;

    seq = tp->rcv_nxt;

    while ((skb = tcp_recv_skb(sk, seq)) != NULL) {
        int frag_start = 0;
        int frag_end = skb->len;

        if (TCP_SKB_CB(skb)->flags & TCPCB_FLAG_URG) {
            int urgent = TCP_SKB_CB(skb)->urg_ptr;
            if (urgent <= (int)(seq - seq))
                continue;
            frag_end = min(frag_end, urgent);
        }

        copied += recv_actor(desc, skb, frag_start, frag_end - frag_start);
        seq += frag_end - frag_start;
        tp->rcv_nxt = seq;
    }

    tcp_cleanup_rbuf(sk, copied);
    return copied;
