int tcp_recv_data(struct sock *sk, read_descriptor_t *desc, sk_read_actor_t recv_actor)
{
    int copied = 0;
    struct sk_buff *skb;

    if (sk->sk_state == TCP_LISTEN)
        return -EINVAL;

    while ((skb = tcp_recv_skb(sk)) != NULL) {
        int offset = 0;
        int frag;

        if (TCP_SKB_CB(skb)->seq == TCP_SKB_CB(skb)->end_seq)
            continue;

        for (frag = 0; frag < skb_shinfo(skb)->nr_frags; ++frag) {
            int len = skb_shinfo(skb)->frags[frag].size;
            int ret;

            ret = recv_actor(desc, skb, offset, len);
            if (ret < 0)
                return ret;
            copied += ret;
            offset += ret;
        }
    }

    tcp_cleanup_rbuf(sk);
    tcp_adjust_rcv_space(sk);

    return copied;
}

int tcp_read_sock(struct sock *sk, read_descriptor_t *desc, sk_read_actor_t recv_actor)
{
    int copied = 0;
    struct sk_buff *skb;
    struct tcphdr *th;
    int offset;

    if (sk->sk_state == TCP_LISTEN)
        return -EINVAL;

    while ((skb = skb_dequeue(&sk->sk_receive_queue)) != NULL) {
        th = (struct tcphdr *)skb->data;
        offset = 0;

        while (offset < skb->len) {
            int len = skb->len - offset;
            int err;

            if (len > 0) {
                struct kvec iov = {
                    .iov_base = skb->data + offset,
                    .iov_len = len,
                };

                err = recv_actor(desc, &iov, 1, &offset);
                if (err <= 0) {
                    if (!copied)
                        copied = err;
                    skb_queue_head(&sk->sk_receive_queue, skb);
                    return copied;
                }

                copied += err;
                offset += err;
            } else {
                break;
            }
        }

        kfree_skb(skb);
    }

    return copied;
}

