int tcp_read_sock(struct sock *sk, read_descriptor_t *desc, sk_read_actor_t recv_actor)
{
    int copied = 0;
    struct sk_buff *skb;
    int err = 0;
    int target;
    int copied_in_this_skb;
    size_t act_size;
    size_t offset;
    int in_peeking = 0;

    if (sk->sk_state == TCP_LISTEN)
        return -EINVAL;

    while ((skb = skb_peek(&sk->sk_receive_queue)) != NULL) {
        target = 0;
        offset = 0;

        if (skb->len - offset <= 0)
            continue;

        if (desc->count == 0)
            break;

        act_size = skb->len - offset;
        if (act_size > desc->count)
            act_size = desc->count;

        if (copied != 0)
            sock_rspace(sk)->target = 0;

        copied_in_this_skb = recv_actor(desc, skb, offset, act_size);
        if (copied_in_this_skb < 0) {
            err = copied_in_this_skb;
            break;
        }

        copied += copied_in_this_skb;
        desc->count -= copied_in_this_skb;
    }

    if (copied)
        __skb_queue_purge(&sk->sk_receive_queue);

    if (copied || err)
        return (err ? err : copied);

    return 0;
}
